var inner_f = function (args) {
  try {
    if (!args || typeof args.spec !== 'string') {
      return { success: false, error: 'Missing required string argument: spec' };
    }

    var spec = args.spec;

    function escapeHtml(text) {
      return String(text)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/\"/g, '&quot;')
        .replace(/'/g, '&#39;');
    }

    var html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Mermaid Diagram Viewer</title>
  <script src="https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.min.js"></script>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      width: 100%;
      height: 100%;
      background: #e6e6e6;
      font-family: Arial, sans-serif;
      overflow: hidden;
    }
    .app {
      display: flex;
      flex-direction: column;
      width: 100%;
      height: 100%;
    }
    .toolbar {
      display: flex;
      gap: 8px;
      padding: 10px;
      background: #f2f2f2;
      border-bottom: 1px solid #cfcfcf;
      align-items: center;
      flex-wrap: wrap;
    }
    .toolbar button {
      padding: 8px 12px;
      border: 1px solid #999;
      background: white;
      cursor: pointer;
      border-radius: 4px;
    }
    .toolbar button:hover {
      background: #f7f7f7;
    }
    .toolbar .status {
      color: #555;
      font-size: 14px;
    }
    .content {
      display: flex;
      flex: 1;
      min-height: 0;
    }
    .leftPane {
      flex: 1;
      min-width: 0;
      display: flex;
      flex-direction: column;
      border-right: 1px solid #cfcfcf;
    }
    .viewer {
      position: relative;
      flex: 1;
      overflow: hidden;
      background: #ffffff;
      cursor: grab;
    }
    .viewer.grabbing {
      cursor: grabbing;
    }
    .viewport {
      position: absolute;
      left: 0;
      top: 0;
      transform-origin: 0 0;
    }
    #diagramContainer {
      padding: 20px;
      display: inline-block;
    }
    .rightPane {
      width: 35%;
      min-width: 260px;
      max-width: 50%;
      display: flex;
      flex-direction: column;
      background: #ededed;
    }
    .paneHeader {
      padding: 10px;
      font-weight: bold;
      border-bottom: 1px solid #cfcfcf;
      background: #f7f7f7;
    }
    textarea {
      flex: 1;
      width: 100%;
      box-sizing: border-box;
      border: none;
      outline: none;
      padding: 12px;
      font-family: Consolas, monospace;
      font-size: 14px;
      resize: both;
      min-height: 180px;
      background: #fafafa;
    }
    .footer {
      padding: 8px 10px;
      font-size: 12px;
      color: #666;
      border-top: 1px solid #cfcfcf;
      background: #f7f7f7;
    }
    .error {
      color: #b00020;
      padding: 12px;
      white-space: pre-wrap;
      font-family: Consolas, monospace;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <button id="zoomInBtn" type="button">Zoom In</button>
      <button id="zoomOutBtn" type="button">Zoom Out</button>
      <button id="resetBtn" type="button">Reset View</button>
      <button id="fitBtn" type="button">Fit</button>
      <button id="renderBtn" type="button">Render</button>
      <span class="status" id="statusText">Ready</span>
    </div>
    <div class="content">
      <div class="leftPane">
        <div class="paneHeader">Diagram</div>
        <div class="viewer" id="viewer">
          <div class="viewport" id="viewport">
            <div id="diagramContainer"></div>
          </div>
        </div>
      </div>
      <div class="rightPane">
        <div class="paneHeader">Mermaid Specification</div>
        <textarea id="specArea">${escapeHtml(spec)}</textarea>
        <div class="footer">The textarea is resizable. Edit the spec and click Render.</div>
      </div>
    </div>
  </div>
  <script>
    (function(){
      var viewer = document.getElementById('viewer');
      var viewport = document.getElementById('viewport');
      var diagramContainer = document.getElementById('diagramContainer');
      var specArea = document.getElementById('specArea');
      var statusText = document.getElementById('statusText');
      var zoom = 1;
      var panX = 0;
      var panY = 0;
      var isDragging = false;
      var dragStartX = 0;
      var dragStartY = 0;
      var startPanX = 0;
      var startPanY = 0;
      var renderCounter = 0;

      mermaid.initialize({ startOnLoad: false, securityLevel: 'loose', theme: 'default' });

      function updateTransform() {
        viewport.style.transform = 'translate(' + panX + 'px, ' + panY + 'px) scale(' + zoom + ')';
        statusText.textContent = 'Zoom: ' + Math.round(zoom * 100) + '%  Pan: (' + Math.round(panX) + ', ' + Math.round(panY) + ')';
      }

      function setZoom(newZoom, centerX, centerY) {
        var clamped = Math.max(0.1, Math.min(5, newZoom));
        var rect = viewer.getBoundingClientRect();
        var cx = typeof centerX === 'number' ? centerX : rect.width / 2;
        var cy = typeof centerY === 'number' ? centerY : rect.height / 2;
        var worldX = (cx - panX) / zoom;
        var worldY = (cy - panY) / zoom;
        zoom = clamped;
        panX = cx - worldX * zoom;
        panY = cy - worldY * zoom;
        updateTransform();
      }

      function resetView() {
        zoom = 1;
        panX = 20;
        panY = 20;
        updateTransform();
      }

      function fitDiagram() {
        var svg = diagramContainer.querySelector('svg');
        if (!svg) {
          resetView();
          return;
        }
        var viewerRect = viewer.getBoundingClientRect();
        var bbox = svg.getBBox();
        var padding = 40;
        var scaleX = (viewerRect.width - padding * 2) / Math.max(1, bbox.width);
        var scaleY = (viewerRect.height - padding * 2) / Math.max(1, bbox.height);
        zoom = Math.max(0.1, Math.min(5, Math.min(scaleX, scaleY)));
        panX = (viewerRect.width - bbox.width * zoom) / 2 - bbox.x * zoom;
        panY = (viewerRect.height - bbox.height * zoom) / 2 - bbox.y * zoom;
        updateTransform();
      }

      async function renderDiagram() {
        var source = specArea.value;
        renderCounter += 1;
        var id = 'mermaid_render_' + renderCounter;
        statusText.textContent = 'Rendering...';
        diagramContainer.innerHTML = '';
        try {
          var result = await mermaid.render(id, source);
          diagramContainer.innerHTML = result.svg;
          var svg = diagramContainer.querySelector('svg');
          if (svg) {
            svg.style.maxWidth = 'none';
            svg.style.height = 'auto';
          }
          fitDiagram();
          statusText.textContent = 'Rendered successfully';
        } catch (err) {
          diagramContainer.innerHTML = '<div class="error">' + String(err && err.message ? err.message : err) + '</div>';
          statusText.textContent = 'Render error';
        }
      }

      document.getElementById('zoomInBtn').addEventListener('click', function(){ setZoom(zoom * 1.2); });
      document.getElementById('zoomOutBtn').addEventListener('click', function(){ setZoom(zoom / 1.2); });
      document.getElementById('resetBtn').addEventListener('click', function(){ resetView(); });
      document.getElementById('fitBtn').addEventListener('click', function(){ fitDiagram(); });
      document.getElementById('renderBtn').addEventListener('click', function(){ renderDiagram(); });

      viewer.addEventListener('mousedown', function(e){
        isDragging = true;
        dragStartX = e.clientX;
        dragStartY = e.clientY;
        startPanX = panX;
        startPanY = panY;
        viewer.classList.add('grabbing');
      });

      window.addEventListener('mousemove', function(e){
        if (!isDragging) return;
        panX = startPanX + (e.clientX - dragStartX);
        panY = startPanY + (e.clientY - dragStartY);
        updateTransform();
      });

      window.addEventListener('mouseup', function(){
        isDragging = false;
        viewer.classList.remove('grabbing');
      });

      viewer.addEventListener('wheel', function(e){
        e.preventDefault();
        var rect = viewer.getBoundingClientRect();
        var cx = e.clientX - rect.left;
        var cy = e.clientY - rect.top;
        if (e.deltaY < 0) {
          setZoom(zoom * 1.1, cx, cy);
        } else {
          setZoom(zoom / 1.1, cx, cy);
        }
      }, { passive: false });

      window.addEventListener('resize', function(){ fitDiagram(); });

      resetView();
      renderDiagram();
    })();
  </script>
</body>
</html>`;

    showToUser(html);
    return { success: true, message: 'Mermaid diagram viewer displayed.' };
  } catch (error) {
    return { success: false, error: String(error && error.message ? error.message : error) };
  }
}; var ret = await inner_f(args); return ret;
